FUNCTION_BLOCK FB_S10
VAR_INPUT
    VFDFaultCode : WORD;
    VFDRun : BOOL;
    ResetBtn : BOOL;
END_VAR
VAR_OUTPUT
    AlarmLamp : BOOL := FALSE;
    TripOutput : BOOL := FALSE;
    Status : WORD := WORD#16#0000;
END_VAR
VAR
    ResetBtnLast : BOOL := FALSE;
    ResetRise : BOOL := FALSE;
    LatchedFaultCode : WORD := WORD#16#0000;
    HeavyFault : BOOL := FALSE;
    RunningFault : BOOL := FALSE;
END_VAR

(*
    每次调用代表20 ms扫描。

    需求冲突报告（待审，不能同时满足全部原文及LTL）：
    1. 原文要求1：0001只报警、不跳闸；
       原文要求4/K4：运行时任何非零故障均立即跳闸。
       本实现采用安全优先：运行中的0001也触发跳闸。
       C1排除0001，未完整表达原文K4。

    2. C2要求TripOutput时VFDRun必须为FALSE；
       VFDRun是只读运行反馈，不能由本块改变。
       当运行反馈为TRUE并出现重故障时，立即跳闸要求与C2冲突。
       本实现立即置TripOutput，但不能保证C2或外部反馈的后续变化。

    3. C10要求上电前两个扫描输出均无故障，
       与首扫描已有重故障时必须同周期跳闸的K1冲突。
       本实现按声明初始化输出，但首次调用即处理输入，不延迟安全动作。

    跳闸统一保持至无故障时的复位上升沿。
    重故障码优先锁存；其他运行故障不覆盖已有重故障码。
    未锁存时，Status直接反映当前输入故障码。
    未声称已通过编译或逐周期功能验证。
*)

ResetRise := ResetBtn AND NOT ResetBtnLast;

HeavyFault :=
    (VFDFaultCode = WORD#16#0002) OR
    (VFDFaultCode = WORD#16#0003);

RunningFault :=
    VFDRun AND (VFDFaultCode <> WORD#16#0000);

(* 故障处理优先；故障存在时复位无效。 *)
IF HeavyFault THEN
    TripOutput := TRUE;
    LatchedFaultCode := VFDFaultCode;
ELSIF RunningFault THEN
    TripOutput := TRUE;
    IF LatchedFaultCode = WORD#16#0000 THEN
        LatchedFaultCode := VFDFaultCode;
    END_IF;
ELSIF ResetRise AND (VFDFaultCode = WORD#16#0000) THEN
    TripOutput := FALSE;
    LatchedFaultCode := WORD#16#0000;
END_IF;

IF LatchedFaultCode <> WORD#16#0000 THEN
    Status := LatchedFaultCode;
ELSE
    Status := VFDFaultCode;
END_IF;

AlarmLamp :=
    (VFDFaultCode <> WORD#16#0000) OR
    (LatchedFaultCode <> WORD#16#0000) OR
    TripOutput;

(* 即使本次复位无效，也消费按钮上升沿，要求释放后重新按下。 *)
ResetBtnLast := ResetBtn;

END_FUNCTION_BLOCK
